css:
.journeysim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #241a33;
    background: linear-gradient(160deg, #f4f0f8 0%, #efe9f5 100%);
    border-radius: 18px;
}

.journeysim-container * {
    box-sizing: border-box;
}

.journeysim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #2b1b4d 0%, #432a6e 55%, #6a3f9e 100%);
    color: #f7f3fb;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(43, 27, 77, 0.32);
}

.journeysim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.journeysim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #e7cf94;
    background: rgba(255, 255, 255, 0.10);
    padding: 5px 14px;
    border-radius: 999px;
}

.journeysim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e6ddf2;
}

.journeysim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #3c2a5e;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.journeysim-period-counter #currentDay,
.journeysim-period-counter #maxPeriods {
    font-weight: 800;
    color: #2b1b4d;
}

.journeysim-round-name {
    background: #e3d6f2;
    color: #432a6e;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.journeysim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a5b12;
    background: #f7ecd6;
    padding: 4px 12px;
    border-radius: 999px;
}

.journeysim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.journeysim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e3dbef;
    box-shadow: 0 4px 14px rgba(43, 27, 77, 0.06);
    border-top: 4px solid #6a3f9e;
}

.journeysim-card-transfer { border-top-color: #6a3f9e; }
.journeysim-card-engagement { border-top-color: #1f7a6b; }
.journeysim-card-coverage { border-top-color: #2f5fb0; }
.journeysim-card-faculty { border-top-color: #b07d16; }

.journeysim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #715f8a;
}

.journeysim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #2b1b4d;
}

.journeysim-card-transfer .journeysim-value { color: #6a3f9e; }
.journeysim-card-engagement .journeysim-value { color: #1f7a6b; }
.journeysim-card-coverage .journeysim-value { color: #2f5fb0; }
.journeysim-card-faculty .journeysim-value { color: #b07d16; }

.journeysim-sublabel {
    font-size: 0.76rem;
    color: #847296;
    line-height: 1.35;
}

.journeysim-transfer-fail .journeysim-value { color: #c0392b; }
.journeysim-transfer-target .journeysim-value { color: #1f7a6b; }

.journeysim-engagement-low .journeysim-value { color: #c0392b; }

.journeysim-faculty-over { border-top-color: #c0392b; }
.journeysim-faculty-over .journeysim-value { color: #c0392b; }

.journeysim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #2b1b4d;
    color: #f4ecdc;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.journeysim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #e7cf94;
}

.journeysim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #6a3f9e;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(43, 27, 77, 0.05);
}

.journeysim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.journeysim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #2b1b4d;
    margin-bottom: 6px;
}

.journeysim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3a2c52;
}

.journeysim-briefing-text strong { color: #1f7a6b; }
.journeysim-briefing-text em { color: #9a5b12; font-style: italic; }

.journeysim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e3dbef;
    box-shadow: 0 4px 14px rgba(43, 27, 77, 0.06);
}

.journeysim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #2b1b4d;
    border-bottom: 2px solid #ece4f5;
    padding-bottom: 8px;
}

.journeysim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #34254f;
    margin: 14px 0 6px;
}

.journeysim-container select,
.journeysim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cdbfdf;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #faf7fd;
    color: #241a33;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.journeysim-container select:focus,
.journeysim-container input[type="number"]:focus {
    outline: none;
    border-color: #6a3f9e;
    box-shadow: 0 0 0 3px rgba(106, 63, 158, 0.16);
}

.journeysim-container select option {
    background-color: #ffffff;
    color: #241a33;
}

.journeysim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #6a3f9e;
}

.journeysim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #5a3f85;
    margin-top: 4px;
}

.journeysim-range-readout span {
    color: #1f7a6b;
    font-weight: 800;
}

.journeysim-range-readout span:first-child {
    color: #5a3f85;
    font-weight: 700;
}

.journeysim-hint {
    font-size: 0.8rem;
    color: #847296;
    margin-top: 4px;
    line-height: 1.4;
}

.journeysim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.journeysim-container .btn-primary {
    background: linear-gradient(135deg, #6a3f9e 0%, #432a6e 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(106, 63, 158, 0.30);
}

.journeysim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.journeysim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #cdbfdf;
    color: #715f8a;
}

.journeysim-coach {
    background: #2b1b4d;
    color: #efe6fa;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(43, 27, 77, 0.24);
}

.journeysim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #c6a6e8;
    margin-bottom: 8px;
}

.journeysim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.journeysim-coach-body strong { color: #e7cf94; }
.journeysim-coach-body em { color: #f0c9a6; font-style: italic; }

.journeysim-history,
.journeysim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e3dbef;
    box-shadow: 0 4px 14px rgba(43, 27, 77, 0.06);
}

.journeysim-history h3,
.journeysim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #2b1b4d;
}

.journeysim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #34254f;
}

.journeysim-container table#usfHistoryTable th {
    background: #f0eaf7;
    color: #2b1b4d;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e0d4f0;
}

.journeysim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f1ebf7;
}

.journeysim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf7fd;
}

.journeysim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .journeysim-container {
        padding: 14px;
    }
    .journeysim-header h1 {
        font-size: 1.7rem;
    }
    .journeysim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .journeysim-value {
        font-size: 2rem;
    }
    .journeysim-clock {
        margin-left: 0;
    }
    .journeysim-period-counter {
        font-size: 0.88rem;
    }
    .journeysim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .journeysim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* v1.1.0 completion message (formatCompletionMessage) */
.journeysim-completion { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #2b1b4d; }
.journeysim-cm-head { display: flex; align-items: center; gap: 18px; flex-wrap: wrap; padding-bottom: 14px; border-bottom: 1px solid rgba(43,27,77,0.14); margin-bottom: 16px; }
.journeysim-cm-score { font-size: 46px; font-weight: 800; line-height: 1; color: #6a3f9e; }
.journeysim-cm-score-max { font-size: 18px; font-weight: 600; color: #432a6e; margin-left: 2px; }
.journeysim-cm-grade { font-size: 18px; font-weight: 700; color: #2b1b4d; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.journeysim-cm-badge { display: inline-block; font-size: 12px; font-weight: 700; letter-spacing: .02em; padding: 3px 10px; border-radius: 999px; }
.journeysim-cm-yes { background: rgba(31,122,107,0.15); color: #1a6659; }
.journeysim-cm-no { background: rgba(192,57,43,0.12); color: #b03325; }
.journeysim-cm-warn { background: rgba(138,109,31,0.16); color: #6f5717; }
.journeysim-cm-metrics { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 18px; }
.journeysim-cm-metric { flex: 1 1 120px; background: #f4f0fa; border: 1px solid rgba(43,27,77,0.10); border-radius: 10px; padding: 12px 14px; text-align: center; }
.journeysim-cm-mv { display: block; font-size: 24px; font-weight: 800; color: #2b1b4d; }
.journeysim-cm-ml { display: block; font-size: 12px; font-weight: 600; color: #432a6e; margin-top: 2px; }
.journeysim-cm-insights-title { font-size: 14px; font-weight: 700; text-transform: uppercase; letter-spacing: .04em; color: #432a6e; margin-bottom: 8px; }
.journeysim-cm-insights { margin: 0; padding-left: 20px; }
.journeysim-cm-insights li { font-size: 14px; line-height: 1.5; color: #3a2f4a; margin-bottom: 8px; }

