(function() {
    'use strict';

    class JourneyAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Architect the Leadership Journey`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Méridien / LTC).
            this.START_TRANSFER = 41;       // transfer-to-work %
            this.START_ENGAGEMENT = 72;     // 4.6/5 satisfaction, scaled
            this.START_COVERAGE = 62;       // learning-outcome attainment %
            this.TARGET_TRANSFER = 65;      // sponsor / Dean target
            this.STRETCH_TRANSFER = 80;     // outcome-attainment stretch
            this.TARGET_COVERAGE = 80;      // outcomes mapped & served
            this.ENGAGEMENT_FLOOR = 60;     // below this, sponsors walk (pilot scored 3.2/5)
            this.ENGAGEMENT_HAPPY = 68;     // sponsors comfortable above this
            this.FACULTY_CAP = 144;         // fixed faculty-day envelope
            this.CONTACT_CAP = 18;          // fixed contact days
            this.SPONSOR_BLOCK = 1.4;       // EUR 1.4M sponsor block at risk

            // Base delivery cost of the locked 18-day journey, in faculty-days.
            this.BASE_FACULTY = 70;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    transfer: this.START_TRANSFER,
                    engagement: this.START_ENGAGEMENT,
                    coverage: this.START_COVERAGE,
                    facultyUsed: 0,
                    sponsorSecured: 0,
                    targetMissed: false,
                    overEnvelope: false,
                    transferHistory: [this.START_TRANSFER],
                    engagementHistory: [this.START_ENGAGEMENT],
                    coverageHistory: [this.START_COVERAGE],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    gap: `application`,
                    outcome: `behavioural`,
                    candor: 60,
                    ratio: 60,
                    sequence: `spaced`,
                    mapping: `all`,
                    project: `fund`,
                    coach: 22,
                    senior: 45,
                    measure: `leadlag`,
                    engage: `stretch`,
                    faculty: `redeploy`,
                    conviction: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const gap = document.getElementById(`gapInput`);
                const outcome = document.getElementById(`outcomeInput`);
                const candor = document.getElementById(`candorInput`);
                if (gap) decisions.gap = gap.value;
                if (outcome) decisions.outcome = outcome.value;
                if (candor) decisions.candor = parseInt(candor.value, 10);
                if (!Number.isFinite(decisions.candor) || decisions.candor < 0 || decisions.candor > 100) {
                    warn(`warn_candor_range`); return false;
                }
            } else if (round === 2) {
                const ratio = document.getElementById(`ratioInput`);
                const seq = document.getElementById(`sequenceInput`);
                const map = document.getElementById(`mappingInput`);
                if (ratio) decisions.ratio = parseInt(ratio.value, 10);
                if (seq) decisions.sequence = seq.value;
                if (map) decisions.mapping = map.value;
                if (!Number.isFinite(decisions.ratio) || decisions.ratio < 20 || decisions.ratio > 95) {
                    warn(`warn_ratio_range`); return false;
                }
            } else if (round === 3) {
                const proj = document.getElementById(`projectInput`);
                const coach = document.getElementById(`coachInput`);
                const senior = document.getElementById(`seniorInput`);
                if (proj) decisions.project = proj.value;
                if (coach) decisions.coach = parseInt(coach.value, 10);
                if (senior) decisions.senior = parseInt(senior.value, 10);
                if (!Number.isFinite(decisions.coach) || decisions.coach < 0 || decisions.coach > 40) {
                    warn(`warn_coach_range`); return false;
                }
                if (!Number.isFinite(decisions.senior) || decisions.senior < 0 || decisions.senior > 100) {
                    warn(`warn_senior_range`); return false;
                }
                // Fixed envelope: the locked calendar cannot be exceeded, only re-allocated.
                const projected = state.domainState.facultyUsed + this._round3FacultyDays(decisions);
                if (projected > this.FACULTY_CAP) {
                    warn(`warn_envelope`); return false;
                }
            } else if (round === 4) {
                const me = document.getElementById(`measureInput`);
                const en = document.getElementById(`engageInput`);
                const fa = document.getElementById(`facultyInput`);
                const cv = document.getElementById(`convictionInput`);
                if (me) decisions.measure = me.value;
                if (en) decisions.engage = en.value;
                if (fa) decisions.faculty = fa.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        _round3FacultyDays(d) {
            const projDays = d.project === `fund` ? 20 : (d.project === `half` ? 10 : 0);
            const seniorPremium = Math.round((d.senior / 100) * 30); // senior profs cost ~2x
            return projDays + (d.coach || 0) + seniorPremium;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas: transfer = behaviour change at work; engagement = enjoyment/attendance;
            // coverage = the five outcomes mapped & served; faculty = days drawn from the 144 cap.
            let transferDelta = 0, engagementDelta = 0, coverageDelta = 0;
            let facultyDays = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the APPLICATION/transfer gap, not knowledge/training (Common Error 1).
                if (d.gap === `application`) {
                    transferDelta += 5; coverageDelta += 5; coachKey = `coach_r1_application`;
                } else if (d.gap === `knowledge` || d.gap === `training`) {
                    transferDelta -= 5; coverageDelta -= 3; coachKey = `coach_r1_content`;
                } else {
                    transferDelta -= 7; engagementDelta -= 3; coachKey = `coach_r1_individuals`;
                }

                // Prioritise the under-served BEHAVIOURAL outcomes (need practice, not lecture).
                if (d.outcome === `behavioural`) {
                    transferDelta += 4; coverageDelta += 6;
                    if (d.gap === `application`) coachKey = `coach_r1_diag_sharp`;
                } else if (d.outcome === `cognitive`) {
                    transferDelta -= 4; coverageDelta -= 3; coachKey = `coach_r1_cognitive`;
                } else if (d.outcome === `selfaware`) {
                    coverageDelta += 1;
                } else { // refuse to prioritise
                    coverageDelta -= 5; coachKey = `coach_r1_equal`;
                }

                // Candour: willingness to name a transfer problem, not 'more content'.
                if (d.candor >= 60) { transferDelta += 3; }
                else if (d.candor <= 25) { transferDelta -= 5; coachKey = `coach_r1_lowcandor`; }

                summaryKey = (d.gap === `application` && d.outcome === `behavioural`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Sequence the modules & balance theory with experience (Common Errors 2 & 4).
                const exp = d.ratio; // experiential share %

                // Theory:experiential ratio. A sweet band (~55-72% experiential) lifts transfer
                // while holding engagement. Too theory-heavy stays inert; over ~80% over-stretches.
                if (exp >= 50 && exp <= 72) {
                    transferDelta += 6; engagementDelta += 2; coverageDelta += 2; coachKey = `coach_r2_balanced`;
                } else if (exp > 72 && exp <= 80) {
                    transferDelta += 4; engagementDelta -= 3;
                } else if (exp > 80) {
                    transferDelta += 2; engagementDelta -= 12; coachKey = `coach_r2_overstretch`;
                } else if (exp >= 35) {
                    transferDelta += 1; engagementDelta += 1; coachKey = `coach_r2_stilltheory`;
                } else {
                    transferDelta -= 5; engagementDelta += 1; coachKey = `coach_r2_theoryheavy`;
                }

                // Sequencing arc: spaced cycles beat front-loading; pure experiential loses framing.
                switch (d.sequence) {
                    case `spaced`: transferDelta += 7; engagementDelta += 4; coverageDelta += 3; coachKey = (exp >= 50 && exp <= 72) ? `coach_r2_spacedfit` : `coach_r2_spaced`; break;
                    case `frontload`: transferDelta -= 8; engagementDelta -= 3; coachKey = `coach_r2_frontload`; break;
                    case `experiential`: transferDelta += 1; engagementDelta -= 6; coverageDelta -= 6; coachKey = `coach_r2_noframing`; break;
                }

                // Constructive alignment: map every module to an outcome.
                switch (d.mapping) {
                    case `all`: coverageDelta += 8; transferDelta += 2; break;
                    case `headline`: coverageDelta += 2; break;
                    case `none`: coverageDelta -= 7; coachKey = `coach_r2_nomap`; break;
                }

                summaryKey = (d.sequence === `spaced` && d.mapping === `all` && exp >= 50 && exp <= 80) ? `sum_r2_good` : (exp > 80 ? `sum_r2_overstretch` : `sum_r2_weak`);
            } else if (round === 3) {
                // Allocate faculty & time against the fixed envelope (Common Errors 3 & 5).
                facultyDays = this._round3FacultyDays(d);

                // The action-learning project — the single biggest transfer driver (+15 / 20 days).
                switch (d.project) {
                    case `fund`: transferDelta += 9; engagementDelta -= 2; coverageDelta += 3; coachKey = `coach_r3_project`; break;
                    case `half`: transferDelta += 4; engagementDelta -= 1; coverageDelta += 1; coachKey = `coach_r3_half`; break;
                    case `cut`: transferDelta -= 9; engagementDelta += 1; coverageDelta -= 3; coachKey = `coach_r3_cut`; break;
                }

                // Coaching & reflection time — no 'content', but where behaviour is rehearsed.
                if (d.coach >= 18) { transferDelta += 6; coverageDelta += 2; }
                else if (d.coach >= 8) { transferDelta += 3; }
                else { transferDelta -= 5; engagementDelta -= 2; coachKey = `coach_r3_nocoach`; }

                // Senior-professor share: a little authority helps; loading them on tilts back to
                // lecture and burns faculty-days (they cost ~2x).
                if (d.senior <= 55) { transferDelta += 2; }
                else if (d.senior >= 80) { transferDelta -= 6; engagementDelta -= 3; coachKey = (coachKey === `coach_r3_project`) ? `coach_r3_seniorheavy` : coachKey; }

                summaryKey = (d.project === `fund` && d.coach >= 18 && d.senior <= 60) ? `sum_r3_good` : (d.project === `cut` ? `sum_r3_cutproject` : `sum_r3_weak`);
            } else if (round === 4) {
                // Present & commit to measurement (Common Error 5 + the two objections).
                switch (d.measure) {
                    case `leadlag`: transferDelta += 6; coverageDelta += 4; coachKey = `coach_r4_leadlag`; break;
                    case `endsurvey`: transferDelta -= 5; coachKey = `coach_r4_endsurvey`; break;
                    case `launch`: transferDelta -= 7; engagementDelta -= 2; coachKey = `coach_r4_launch`; break;
                }

                // Sponsor objection: keep stretch AND engagement, don't water it down or dismiss it.
                switch (d.engage) {
                    case `stretch`: engagementDelta += 8; transferDelta += 2; coachKey = (d.measure === `leadlag`) ? `coach_r4_stretch` : coachKey; break;
                    case `soften`: engagementDelta += 4; transferDelta -= 7; coachKey = `coach_r4_soften`; break;
                    case `dismiss`: engagementDelta -= 10; coachKey = `coach_r4_dismiss`; break;
                }

                // Faculty resistance: redeploy beats reverting to lectures.
                switch (d.faculty) {
                    case `redeploy`: transferDelta += 4; coverageDelta += 3; break;
                    case `restore`: transferDelta -= 9; coverageDelta -= 4; engagementDelta += 2; coachKey = `coach_r4_restore`; break;
                    case `ignore`: engagementDelta -= 5; coachKey = `coach_r4_ignore`; break;
                }

                // Conviction nudges the sponsor view.
                engagementDelta += Math.round((d.conviction - 60) / 12);

                summaryKey = (d.measure === `leadlag` && d.engage === `stretch` && d.faculty === `redeploy`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting: faculty-days drawn from the 144 envelope.
            if (round === 2) facultyDays = this.BASE_FACULTY + Math.round((d.ratio - 60) * 0.2);
            ds.facultyUsed = Math.max(0, Math.round(ds.facultyUsed + facultyDays));
            if (ds.facultyUsed > this.FACULTY_CAP) ds.overEnvelope = true;

            // KPIs move on their deltas, clamped 0-100 with headroom kept by modest deltas.
            ds.transfer = Math.max(0, Math.min(100, ds.transfer + transferDelta));
            ds.engagement = Math.max(0, Math.min(100, ds.engagement + engagementDelta));
            ds.coverage = Math.max(0, Math.min(100, ds.coverage + coverageDelta));

            // Sponsor block secured (EUR M): rises with transfer toward target and holds only if
            // engagement stays above the floor. Below the floor, sponsors walk regardless of transfer.
            const transferGain = Math.max(0, Math.min(1, (ds.transfer - this.START_TRANSFER) / (this.TARGET_TRANSFER - this.START_TRANSFER)));
            let engageFactor = ds.engagement >= this.ENGAGEMENT_HAPPY ? 1 : (ds.engagement >= this.ENGAGEMENT_FLOOR ? 0.7 : 0.25);
            ds.sponsorSecured = Math.round(this.SPONSOR_BLOCK * transferGain * engageFactor * 100) / 100;

            ds.transferHistory.push(Math.round(ds.transfer));
            ds.engagementHistory.push(Math.round(ds.engagement));
            ds.coverageHistory.push(Math.round(ds.coverage));

            // v1.1.0: publish composite (0-100) to the reporting/grading layer every period.
            ds.performance = { overallScore: this._composite(ds) };

            if (round === this.ROUNDS.length && ds.transfer < this.TARGET_TRANSFER) ds.targetMissed = true;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                transfer: Math.round(ds.transfer),
                transferDelta: Math.round(transferDelta),
                engagement: Math.round(ds.engagement),
                engagementDelta: Math.round(engagementDelta),
                coverage: Math.round(ds.coverage),
                coverageDelta: Math.round(coverageDelta),
                facultyUsed: ds.facultyUsed,
                sponsorSecured: ds.sponsorSecured,
                overEnvelope: ds.overEnvelope,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);
