                const card = document.querySelector(`.journeysim-card-transfer`);
                if (card) {
                    card.classList.toggle(`journeysim-transfer-target`, Number(v) >= this.TARGET_TRANSFER);
                    card.classList.toggle(`journeysim-transfer-fail`, Number(v) < this.TARGET_TRANSFER);
                }
                return Math.round(Number(v)) + `%`;
            });
            uiManager.bind(`engagementDisplay`, `domainState.engagement`, (v) => {
                const card = document.querySelector(`.journeysim-card-engagement`);
                if (card) card.classList.toggle(`journeysim-engagement-low`, Number(v) < this.ENGAGEMENT_FLOOR);
                return Math.round(Number(v));
            });
            uiManager.bind(`coverageDisplay`, `domainState.coverage`, (v) => Math.round(Number(v)));
            uiManager.bind(`facultyDisplay`, `domainState.facultyUsed`, (v) => {
                const card = document.querySelector(`.journeysim-card-faculty`);
                if (card) card.classList.toggle(`journeysim-faculty-over`, Number(v) > this.FACULTY_CAP);
                return Math.round(Number(v)) + ` / 144`;
            });
            uiManager.bind(`budgetDisplay`, `domainState.sponsorSecured`, (v) => this._money(Number(v)) + ` / ` + this._money(this.SPONSOR_BLOCK));

            const self = this;

            // Candour slider readout.
            this._wireReadout(`candorInput`, `candorReadout`);
            // Senior-professor slider readout.
            this._wireReadout(`seniorInput`, `seniorReadout`);

            // Experiential ratio slider: show experiential AND theory share live.
            const ratio = document.getElementById(`ratioInput`);
            const ratioReadout = document.getElementById(`ratioReadout`);
            const theoryReadout = document.getElementById(`ratioTheoryReadout`);
            const syncRatio = function() {
                const v = parseInt(ratio.value, 10);
                if (ratioReadout) ratioReadout.textContent = v;
                if (theoryReadout) theoryReadout.textContent = (100 - v);
            };
            if (ratio) {
                syncRatio();
                ratio.addEventListener(`input`, syncRatio);
            }
        }

        _wireReadout(inputId, readoutId) {
            const input = document.getElementById(inputId);
            const readout = document.getElementById(readoutId);
            if (input && readout) {
                readout.textContent = input.value;
                input.addEventListener(`input`, function() { readout.textContent = input.value; });
            }
        }

        _money(m) {
            // EUR, symbol after the number per locale; M for millions, k for thousands.
            const lang = window.mySimulation ? window.mySimulation.language : `en`;
            if (lang === `es`) {
                if (m >= 1) return (Math.round(m * 100) / 100).toFixed(2).replace(`.`, `,`) + ` M€`;
                return Math.round(m * 1000) + ` k€`;
            }
            if (m >= 1) return `€` + (Math.round(m * 100) / 100).toFixed(2) + `M`;
            return `€` + Math.round(m * 1000) + `k`;
        }

