        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.transferHistory.map((_, i) => (i === 0 ? `Start` : `R` + i));
            return {
                journeyChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.transferHistory },
                        { data: ds.engagementHistory },
                        { data: ds.coverageHistory }
                    ]
                }
            };
        }

        // Shared composite (0-100). Written to domainState.performance.overallScore each period
        // for the reporting/grading layer. Weights copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            var transfer = Math.round(ds.transfer || 0);
            var engagement = Math.round(ds.engagement || 0);
            var coverage = Math.round(ds.coverage || 0);
            return Math.max(0, Math.min(100, Math.round(Math.min(100, transfer) * 0.40 + engagement * 0.30 + coverage * 0.30)));
        }

        _cl(key, fallback) {
            try {
                if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                    var v = window.mySimulation.t(key);
                    if (v && v !== key) return v;
                }
            } catch (e) {}
            return fallback;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const transfer = Math.round(ds.transfer);
            const engagement = Math.round(ds.engagement);
            const coverage = Math.round(ds.coverage);

            const hitTransfer = transfer >= this.TARGET_TRANSFER;
            const engaged = engagement >= this.ENGAGEMENT_FLOOR;
            const mapped = coverage >= this.TARGET_COVERAGE;
            const overEnvelope = ds.overEnvelope;
            const composite = this._composite(ds);

            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            let performanceKey = `grade_stalled`;
            if (hitTransfer && engaged && mapped && composite >= 72) performanceKey = `grade_rearchitected`;
            else if (hitTransfer && engaged) performanceKey = `grade_credible`;
            else if (hitTransfer && !engaged) performanceKey = `grade_sponsorsout`;
            else if (!hitTransfer && transfer > this.START_TRANSFER + 10) performanceKey = `grade_improving`;
            else if (overEnvelope) performanceKey = `grade_overenvelope`;
            const performance = T(performanceKey);

            const insights = [];
            if (hitTransfer && engaged && mapped) insights.push(window.mySimulation.t(`insight_rearchitected`));
            else if (hitTransfer && !engaged) insights.push(window.mySimulation.t(`insight_sponsorsout`));
            else if (hitTransfer) insights.push(window.mySimulation.t(`insight_thin`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (!engaged) insights.push(window.mySimulation.t(`insight_lowengagement`));
            if (!mapped) insights.push(window.mySimulation.t(`insight_unmapped`));
            if (transfer >= this.STRETCH_TRANSFER) insights.push(window.mySimulation.t(`insight_stretch`));
            if (ds.sponsorSecured >= this.SPONSOR_BLOCK - 0.05) insights.push(window.mySimulation.t(`insight_sponsorsecured`));

            return {
                transfer: transfer,
                engagement: engagement,
                coverage: coverage,
                sponsorSecured: ds.sponsorSecured,
                hitTransfer: hitTransfer,
                engaged: engaged,
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                overEnvelope: overEnvelope,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            var grade = s.performance || (s.performanceKey ? T(s.performanceKey) : '');
            var met = !!s.hitTransfer;
            var badge = met
                ? '<span class="journeysim-cm-badge journeysim-cm-yes">' + T('cm_met') + '</span>'
                : '<span class="journeysim-cm-badge journeysim-cm-no">' + T('cm_missed') + '</span>';
            var envBadge = s.overEnvelope
                ? '<span class="journeysim-cm-badge journeysim-cm-warn">' + T('cm_envelope_badge') + '</span>'
                : '';
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var items = insights.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var metrics = ''
                + '<div class="journeysim-cm-metric"><span class="journeysim-cm-mv">' + Math.round(s.transfer || 0) + '%</span><span class="journeysim-cm-ml">' + T('cm_m_transfer') + '</span></div>'
                + '<div class="journeysim-cm-metric"><span class="journeysim-cm-mv">' + Math.round(s.engagement || 0) + '</span><span class="journeysim-cm-ml">' + T('cm_m_engagement') + '</span></div>'
                + '<div class="journeysim-cm-metric"><span class="journeysim-cm-mv">' + Math.round(s.coverage || 0) + '</span><span class="journeysim-cm-ml">' + T('cm_m_coverage') + '</span></div>';
            return ''
                + '<div class="journeysim-completion">'
                +   '<div class="journeysim-cm-head">'
                +     '<div class="journeysim-cm-score">' + score + '<span class="journeysim-cm-score-max">/100</span></div>'
                +     '<div class="journeysim-cm-grade">' + grade + ' ' + badge + envBadge + '</div>'
                +   '</div>'
                +   '<div class="journeysim-cm-metrics">' + metrics + '</div>'
                +   '<div class="journeysim-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="journeysim-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.engagement < this.ENGAGEMENT_FLOOR) return window.mySimulation.t(`hint_engagement`);
            if (ds.overEnvelope) return window.mySimulation.t(`hint_envelope`);
            if (ds.coverage < 60 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_coverage`);
            if (state.currentPeriod >= 3 && ds.transfer < 55) return window.mySimulation.t(`hint_behind`);
            if (ds.transfer >= this.TARGET_TRANSFER && ds.engagement >= this.ENGAGEMENT_HAPPY && ds.coverage >= this.TARGET_COVERAGE) return window.mySimulation.t(`hint_strong`);
            return null;
        }

